// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CameraDevice) predicate.CameraDevice {
	return predicate.CameraDevice(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CameraDevice) predicate.CameraDevice {
	return predicate.CameraDevice(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CameraDevice) predicate.CameraDevice {
	return predicate.CameraDevice(sql.NotPredicates(p))
}
